+import { Badge } from '@/components/ui/badge';
+import {
+  Tooltip,
+  TooltipContent,
+  TooltipPortal,
+  TooltipProvider,
+  TooltipTrigger
+} from '@/components/ui/tooltip';
+import { CoinPoolWithAccess } from '@/data/admin/coin-pools';
+import { AdminRole } from '@/types/admin';
+
+import CoinPoolActions from './coin-pool-actions';
+
+interface CoinPoolTableRowProps {
+  pool: CoinPoolWithAccess;
+  index: number;
+  page: number;
+  itemsPerPage: number;
+  currentUserRole: AdminRole;
+  currentUserId?: string;
+}
+
+export default function CoinPoolTableRow({
+  pool,
+  index,
+  page,
+  itemsPerPage,
+  currentUserRole,
+  currentUserId
+}: CoinPoolTableRowProps) {
+  const t = useTranslations('admin.coinPoolAccess');
+  const tTable = useTranslations('admin.coinPoolManagement.table');
+  const serialNumber = index + 1 + (page - 1) * itemsPerPage;
+  const { coinPoolAccess } = pool;
+
+  const renderBusinessAdmin = () => {
+    if (coinPoolAccess.length === 0) {
+      return (
+        <Badge
+          variant="outline"
+          className="text-muted-foreground rounded-full whitespace-nowrap font-medium"
+        >
+          {t('none')}
+        </Badge>
+      );
+    }
+    if (coinPoolAccess.length === 1) {
+      const user = coinPoolAccess[0]?.user;
+      const displayName = user?.name || user?.email || 'Unknown';
+      return (
+        <Badge
+          variant="outline"
+          className="border-gray-200 bg-gray-100 text-gray-700 rounded-full whitespace-nowrap font-medium"
+        >
+          {displayName}
+        </Badge>
+      );
+    }
+    return (
+      <TooltipProvider delayDuration={300}>
+        <Tooltip>
+          <TooltipTrigger asChild>
+            <div className="inline-block">
+              <Badge
+                variant="outline"
+                className="border-gray-200 bg-gray-100 text-gray-700 rounded-full cursor-help hover:bg-gray-200 whitespace-nowrap font-medium"
+              >
+                {coinPoolAccess.length} {tTable('businessAdmin')}
+              </Badge>
+            </div>
+          </TooltipTrigger>
+          <TooltipPortal>
+            <TooltipContent
+              side="top"
+              align="center"
+              className="max-w-xs z-[9999]"
+              sideOffset={5}
+            >
+              <div className="space-y-1">
+                {coinPoolAccess.map((access) => (
+                  <div key={access.id} className="text-xs">
+                    • {access.user.name || access.user.email || 'Unknown'}
+                  </div>
+                ))}
+              </div>
+            </TooltipContent>
+          </TooltipPortal>
+        </Tooltip>
+      </TooltipProvider>
+    );
+  };
+
+  return (
+    <TableRow key={`coin-pool-row-${pool.id}`}>
+      <TableCell>{serialNumber}</TableCell>
+      <TableCell>
+        <div className="flex flex-col">
+          <div>{pool.name || '-'}</div>
+          <div className="text-xs text-muted-foreground">
+            {pool.email || '-'}
+          </div>
+        </div>
+      </TableCell>
+      <TableCell>
+        <span className="font-mono text-sm">
+          {pool.tokenBalance.toLocaleString()}
+        </span>
+      </TableCell>
+      <TableCell>
+        <span
+          className={`font-mono text-sm ${
+            pool.availableBalance < 0 ? 'text-destructive font-medium' : ''
+          }`}
+        >
+          {pool.availableBalance.toLocaleString()}
+        </span>
+      </TableCell>
+      <TableCell>
+        <div className="flex items-center">{renderBusinessAdmin()}</div>
+      </TableCell>
+      <TableCell>
+        <CoinPoolActions
+          pool={pool}
+          currentUserRole={currentUserRole}
+          currentUserId={currentUserId}
+        />
+      </TableCell>
+    </TableRow>
+  );
+}
