index 0000000..0d0a19b
--- /dev/null
+++ b/components/canvas/floating/FloatingQuickActions.tsx
@@ -0,0 +1,251 @@
+'use client';
+
+import { useCallback, useRef, useEffect } from 'react';
+import { Download, Share, Copy, Trash2 } from 'lucide-react';
+import { toast } from 'sonner';
+import { useTranslations } from 'next-intl';
+import mixpanel from 'mixpanel-browser';
+
+import { ImageObject, isImageObject } from '@/components/canvas/types';
+import { isImageSelection } from '@/hooks/use-selection-state';
+import { useFloatingElementPosition } from '@/hooks/use-floating-element-position';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { useImageDragStore } from '@/store/image-drag-store';
+import { useSelectionStore } from '@/store/selection-store';
+import { useCanvasStore } from '@/store/canvas-store';
+import { triggerDownload } from '@/utils/download';
+import { isPlaceholderImage } from '@/utils/canvas/object';
+import { useCopyPaste } from '@/hooks/use-copy-paste';
+import useCanvasDelete from '@/hooks/use-canvas-delete';
+import { useImagePublishStore } from '@/store/canvas/image-publish-store';
+import { cn } from '@/lib/utils';
+
+export function FloatingQuickActions() {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const t = useTranslations('Canvas');
+  const isReadOnly = useCanvasStore((state) => state.isReadOnly);
+
+  // Selection state
+  const selection = useSelectionStore((state) => state.selection);
+  const firstSelected = selection.selected[0];
+
+  // Canvas objects
+  const { canvasObjects } = useHistoryState();
+
+  // Check if single image is selected
+  const isSingleImageSelected =
+    selection.selected.length === 1 && isImageSelection(firstSelected);
+
+  // Get the selected image object
+  const getSelectedImage = useCallback((): ImageObject | undefined => {
+    if (!isSingleImageSelected || !firstSelected) return undefined;
+    const obj = canvasObjects.find((o) => o.id === firstSelected.id);
+    return obj && isImageObject(obj) ? obj : undefined;
+  }, [isSingleImageSelected, firstSelected, canvasObjects]);
+
+  const selectedImage = getSelectedImage();
+
+  // Position hook — anchor to top-right of the image, 8px above
+  const { updatePosition, updatePositionForObject } =
+    useFloatingElementPosition({
+      containerRef,
+      getTargetObject: getSelectedImage,
+      anchor: 'top-right',
+      offset: { x: 0, y: -40 }
+    });
+
+  // Subscribe to canvas transform (zoom/pan)
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+
+  // Update position when selection changes
+  useEffect(() => {
+    if (selectedImage) {
+      updatePosition();
+    }
+  }, [selectedImage, updatePosition]);
+
+  // Update position when transform changes (zoom/pan)
+  useEffect(() => {
+    if (selectedImage) {
+      updatePosition();
+    }
+  }, [position.x, position.y, scale, selectedImage, updatePosition]);
+
+  // Subscribe to real-time drag/transform
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+
+  const isDraggingThisImage =
+    draggingImageId && selectedImage && draggingImageId === selectedImage.id;
+
+  // Update position when image properties change (after drag ends)
+  useEffect(() => {
+    if (selectedImage && !isDraggingThisImage) {
+      updatePositionForObject(selectedImage);
+    }
+  }, [
+    selectedImage?.position.x,
+    selectedImage?.position.y,
+    selectedImage?.width,
+    selectedImage?.height,
+    selectedImage?.scaleX,
+    selectedImage?.scaleY,
+    selectedImage,
+    isDraggingThisImage,
+    updatePositionForObject
+  ]);
+
+  // Update position during drag/transform (real-time)
+  useEffect(() => {
+    if (
+      isDraggingThisImage &&
+      dragPosition &&
+      dragDimensions &&
+      selectedImage
+    ) {
+      const tempImage: ImageObject = {
+        ...selectedImage,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? selectedImage.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? selectedImage.scaleY ?? 1
+      };
+      updatePositionForObject(tempImage);
+    }
+  }, [
+    isDraggingThisImage,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    selectedImage,
+    updatePositionForObject
+  ]);
+
+  // Action hooks
+  const { handleDuplicate } = useCopyPaste();
+  const { handleDelete } = useCanvasDelete();
+
+  // --- Action handlers ---
+
+  const handleDownload = useCallback(() => {
+    if (!selectedImage) return;
+
+    const src = Array.isArray(selectedImage.src)
+      ? selectedImage.src[selectedImage.currentIndex ?? 0] ??
+        selectedImage.src[0]
+      : selectedImage.src;
+
+    if (!src) {
+      toast.error(t('actionsInfo.download.noImageSelected'));
+      return;
+    }
+
+    const filename = `image-${selectedImage.id.slice(0, 8)}.png`;
+    triggerDownload(src, filename);
+    toast.success(t('actionsInfo.download.imageDownloadedSuccessfully'));
+
+    mixpanel.track('[Canvas] Quick Action - Download', {
+      imageId: selectedImage.id
+    });
+  }, [selectedImage, t]);
+
+  const requestImagePublish = useImagePublishStore(
+    (state) => state.requestImagePublish
+  );
+
+  const handlePublish = useCallback(() => {
+    if (!selectedImage) return;
+
+    requestImagePublish('quick_actions');
+
+    mixpanel.track('[Canvas] Quick Action - Publish', {
+      imageId: selectedImage.id
+    });
+  }, [selectedImage, requestImagePublish]);
+
+  const handleDuplicateAction = useCallback(() => {
+    if (!selectedImage) return;
+    handleDuplicate();
+
+    mixpanel.track('[Canvas] Quick Action - Duplicate', {
+      imageId: selectedImage.id
+    });
+  }, [selectedImage, handleDuplicate]);
+
+  const handleDeleteAction = useCallback(() => {
+    if (!selectedImage) return;
+    if (selectedImage.isLocked) return;
+    handleDelete({ id: selectedImage.id });
+
+    mixpanel.track('[Canvas] Quick Action - Delete', {
+      imageId: selectedImage.id
+    });
+  }, [selectedImage, handleDelete]);
+
+  // Visibility
+  const visible = isSingleImageSelected && !!selectedImage && !isReadOnly;
+  const isPlaceholder = selectedImage
+    ? isPlaceholderImage(selectedImage)
+    : true;
+  const isLocked = selectedImage?.isLocked ?? false;
+
+  if (!visible) return null;
+
+  return (
+    <div
+      ref={containerRef}
+      className={cn(
+        'absolute z-20 pointer-events-auto',
+        'transition-opacity duration-150',
+        isDraggingThisImage ? 'opacity-50' : 'opacity-100'
+      )}
+      style={{ transform: 'translateX(-100%)' }}
+    >
+      <div className="flex items-center gap-0.5 bg-background/80 backdrop-blur-md rounded-lg shadow-lg p-1">
+        {/* Download */}
+        <button
+          className="p-1.5 rounded-md hover:bg-gray-100 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
+          onClick={handleDownload}
+          disabled={isPlaceholder}
+          title={t('quickActions.download')}
+        >
+          <Download size={16} />
+        </button>
+
+        {/* Publish */}
+        <button
+          className="p-1.5 rounded-md hover:bg-gray-100 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
+          onClick={handlePublish}
+          disabled={isPlaceholder}
+          title={t('quickActions.publish')}
+        >
+          <Share size={16} />
+        </button>
+
+        {/* Duplicate */}
+        <button
+          className="p-1.5 rounded-md hover:bg-gray-100 transition-colors"
+          onClick={handleDuplicateAction}
+          title={t('quickActions.duplicate')}
+        >
+          <Copy size={16} />
+        </button>
+
+        {/* Delete */}
+        <button
+          className="p-1.5 rounded-md hover:bg-gray-100 hover:text-red-500 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
+          onClick={handleDeleteAction}
+          disabled={isLocked}
+          title={t('quickActions.delete')}
+        >
+          <Trash2 size={16} />
+        </button>
+      </div>
+    </div>
+  );
+}
