+  const tTransfer = useTranslations('admin.users.transferToken');
+  const pathname = usePathname();
+  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
+  const [isTransferTokenDialogOpen, setIsTransferTokenDialogOpen] =
+    useState(false);
+
+  const invitationCodesUrl = `${pathname.replace(
+    /\/admin\/coin-pools.*/,
+    '/admin/invitation-codes'
+  )}?coinPoolIds=${pool.id}`;
+
+  const isSystemAdmin = currentUserRole === 'system-admin';
+  const isBusinessAdmin = currentUserRole === 'business-admin';
+  const canTransferTokens = isSystemAdmin || isBusinessAdmin;
+
+  const actions = [
+    {
+      label: t('viewInvitationCodes'),
+      onClick: () => {
+        window.open(invitationCodesUrl, '_blank', 'noopener,noreferrer');
+      },
+      icon: <Ticket className="w-4 h-4" />
+    },
+    ...(canTransferTokens
+      ? [
+          {
+            label: tTransfer('title'),
+            onClick: () => {
+              setIsTransferTokenDialogOpen(true);
+            },
+            icon: <Coins className="w-4 h-4" />
+          }
+        ]
+      : []),
+    {
+      label: t('editAccess'),
+      onClick: () => {
+        setIsEditDialogOpen(true);
+      },
+      icon: <Edit3 className="w-4 h-4" />
+    }
+  ];
+
+  return (
+    <>
+      <ActionDropdownMenu actions={actions} />
+      <EditCoinPoolAccessDialog
+        pool={pool}
+        open={isEditDialogOpen}
+        onOpenChange={setIsEditDialogOpen}
+      />
+      <TransferTokenDialog
+        open={isTransferTokenDialogOpen}
+        onOpenChange={setIsTransferTokenDialogOpen}
+        targetUserId={pool.id}
+        currentUserRole={currentUserRole}
+        currentUserId={currentUserId}
+      />
+    </>
+  );
+}
