+import { getTranslations } from 'next-intl/server';
+
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { getAdminCoinPools } from '@/data/admin/coin-pools';
+import { getCurrentUserAdminRoles } from '@/data/admin/roles';
+import { currentUser } from '@/lib/auth';
+import { AdminPageGuard } from '@/components/admin/permission-guard';
+
+import AdminPageHeader from '../_components/admin-page-header';
+import Pagination from '../users/_components/pagination';
+
+import CoinPoolSearchForm from './_components/coin-pool-search-form';
+import CoinPoolsTable from './_components/coin-pools-table';
+import CreateCoinPoolDialog from './_components/create-coin-pool-dialog';
+
+const PAGINATION_PAGES_TO_SHOW = 10;
+const ITEMS_PER_PAGE = 10;
+
+interface CoinPoolsPageProps {
+  searchParams: {
+    page?: string;
+    nameSearch?: string;
+    businessAdminUserId?: string;
+  };
+}
+
+export default async function CoinPoolsPage({
+  searchParams
+}: CoinPoolsPageProps) {
+  const t = await getTranslations('admin');
+
+  const page = Number(searchParams.page) || 1;
+  const nameSearch =
+    typeof searchParams.nameSearch === 'string' ? searchParams.nameSearch : '';
+  const businessAdminUserId =
+    typeof searchParams.businessAdminUserId === 'string'
+      ? searchParams.businessAdminUserId
+      : '';
+
+  const hasCoinPoolsPermission =
+    await checkCurrentUserPermission('write-coinpools');
+
+  const [session, currentUserRoles] = await Promise.all([
+    currentUser(),
+    getCurrentUserAdminRoles()
+  ]);
+  const currentUserRole = currentUserRoles[0]?.name ?? '';
+  const currentUserId = session?.id;
+
