+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { getCurrentUserAdminRoles } from '@/data/admin/roles';
+import createLogger from '@/lib/logger';
+
+const logger = createLogger('admin-coin-pools-data');
+
+const ITEMS_PER_PAGE = 10;
+
+export interface CoinPoolWithAccess {
+  id: string;
+  name: string | null;
+  email: string | null;
+  tokenBalance: number;
+  availableBalance: number;
+  coinPoolAccess: Array<{
+    id: string;
+    user: {
+      id: string;
+      name: string | null;
+      email: string | null;
+    };
+  }>;
+}
+
+export interface CoinPoolPaginationResult {
+  coinPools: CoinPoolWithAccess[];
+  pagination: {
+    total: number;
+    pages: number;
+    current: number;
+  };
+}
+
+export interface CoinPoolSearchParams {
+  page?: number;
+  pageSize?: number;
+  nameSearch?: string;
+  businessAdminUserId?: string;
+}
+
+function calculateTokenBalance(
+  tokenBalances: Array<{
+    remainingAmount: number;
+    expiresAt: Date | null;
+  }>
+): number {
+  const now = new Date();
+  return tokenBalances.reduce((total, balance) => {
+    if (balance.expiresAt && balance.expiresAt > now) {
+      return total + balance.remainingAmount;
+    }
+    return total;
+  }, 0);
+}
+
+/**
+ * 獲取代幣池列表（帶分頁和篩選）
+ * 僅限具 write-coinpools 權限且為 system-admin 或 business-admin 的使用者
+ */
+export async function getAdminCoinPools(
+  params: CoinPoolSearchParams = {}
+): Promise<CoinPoolPaginationResult> {
+  const {
+    page = 1,
+    pageSize = ITEMS_PER_PAGE,
+    nameSearch = '',
+    businessAdminUserId = ''
+  } = params;
+
+  const hasPermission = await checkCurrentUserPermission('write-coinpools');
+  if (!hasPermission) {
+    logger.error('No write-coinpools permission');
+    return {
+      coinPools: [],
+      pagination: { total: 0, pages: 0, current: page }
+    };
+  }
+
+  const adminUser = await currentUser();
+  if (!adminUser?.id) {
+    logger.error('User not logged in');
+    return {
+      coinPools: [],
+      pagination: { total: 0, pages: 0, current: page }
+    };
+  }
+
+  const currentUserRoles = await getCurrentUserAdminRoles();
+  if (currentUserRoles.length === 0) {
+    logger.error('No admin role');
+    return {
+      coinPools: [],
+      pagination: { total: 0, pages: 0, current: page }
+    };
+  }
+
+  const currentUserRole = currentUserRoles[0].name;
+
+  // 僅 system-admin 和 business-admin 可存取代幣池管理列表
+  if (
+    currentUserRole !== 'system-admin' &&
+    currentUserRole !== 'business-admin'
+  ) {
+    logger.error('Role not allowed for coin pool list');
+    return {
+      coinPools: [],
+      pagination: { total: 0, pages: 0, current: page }
+    };
+  }
+
+  const skip = (page - 1) * pageSize;
+
+  const baseWhere: Prisma.UserWhereInput = {
+    userAdminRoles: {
+      some: {
+        adminRole: {
+          name: 'coin-pool-admin'
+        }
+      }
+    }
+  };
+
+  const andConditions: Prisma.UserWhereInput[] = [baseWhere];
+
+  // business-admin 僅能看自己有 CoinPoolAccess 權限的代幣池
+  if (currentUserRole === 'business-admin') {
+    andConditions.push({
+      coinPoolAccess: {
+        some: { userId: adminUser.id }
+      }
+    });
+  }
+
+  if (nameSearch.trim()) {
+    andConditions.push({
+      OR: [
+        { name: { contains: nameSearch.trim(), mode: 'insensitive' } },
+        { email: { contains: nameSearch.trim(), mode: 'insensitive' } }
+      ]
+    });
+  }
+
+  if (businessAdminUserId.trim()) {
+    andConditions.push({
+      coinPoolAccess: {
+        some: { userId: businessAdminUserId.trim() }
+      }
+    });
+  }
+
+  const whereConditions: Prisma.UserWhereInput =
+    andConditions.length === 1 ? andConditions[0] : { AND: andConditions };
+
+  const [users, total] = await Promise.all([
+    prisma.user.findMany({
+      where: whereConditions,
+      select: {
+        id: true,
+        name: true,
+        email: true,
+        tokenBalances: {
+          select: {
+            remainingAmount: true,
+            expiresAt: true
+          }
+        },
+        coinPoolAccess: {
+          select: {
+            id: true,
+            user: {
+              select: {
+                id: true,
+                name: true,
+                email: true
+              }
+            }
+          }
+        }
+      },
+      orderBy: { createdAt: 'desc' },
+      skip,
+      take: pageSize
+    }),
+    prisma.user.count({
+      where: whereConditions
+    })
+  ]);
+
+  const userIds = users.map((u) => u.id);
+  type ReservedRow = { coinPoolId: string; reserved: number };
+  let reservedMap = new Map<string, number>();
+  if (userIds.length > 0) {
+    const now = new Date();
+    const reservedRows = await prisma.$queryRaw<ReservedRow[]>`
+      SELECT "coinPoolId", COALESCE(SUM(("maxUses" - "currentUses") * "tokenAmount"), 0)::integer AS reserved
+      FROM "InvitationCode"
+      WHERE "coinPoolId" IN (${Prisma.join(
+        userIds.map((id) => Prisma.sql`${id}`),
+        ', '
+      )})
+        AND "isActive" = true
+        AND ("expiresAt" IS NULL OR "expiresAt" > ${now})
+      GROUP BY "coinPoolId"
+    `;
+    reservedMap = new Map(
+      reservedRows.map((row) => [row.coinPoolId, Number(row.reserved)])
+    );
+  }
+
+  const coinPools: CoinPoolWithAccess[] = users.map((user) => {
+    const tokenBalance = calculateTokenBalance(user.tokenBalances);
+    const reservedAmount = reservedMap.get(user.id) ?? 0;
+    const availableBalance = tokenBalance - reservedAmount;
+    return {
+      id: user.id,
+      name: user.name,
+      email: user.email,
+      tokenBalance,
+      availableBalance,
+      coinPoolAccess: user.coinPoolAccess.map((access) => ({
+        id: access.id,
+        user: access.user
+      }))
+    };
+  });
+
+  const pages = Math.ceil(total / pageSize) || 1;
+
+  return {
+    coinPools,
+    pagination: {
+      total,
+      pages,
+      current: page
+    }
+  };
+}
